import base64
import itertools
from collections import defaultdict

def read_ciphertexts():
    with open('ctf_files/assignment.txt', 'r') as f:
        content = f.read()

    # Find base64 patterns - long strings of base64 characters
    import re
    b64_pattern = r'[A-Za-z0-9+/=]{20,}'  # Look for base64 strings 20+ chars long
    ciphertexts = re.findall(b64_pattern, content)

    # Decode all ciphertexts
    decoded = []
    for ct in ciphertexts:
        try:
            decoded.append(base64.b64decode(ct))
        except:
            print(f"Failed to decode: {ct}")
    return decoded

def analyze_lengths(ciphertexts):
    # Group by length
    by_length = defaultdict(list)
    for i, ct in enumerate(ciphertexts):
        by_length[len(ct)].append((i, ct))

    # Print statistics
    print("\n=== Length Statistics ===")
    for length, cts in sorted(by_length.items()):
        print(f"Length {length}: {len(cts)} ciphertexts")

    return by_length

def xor_bytes(a, b):
    return bytes(x ^ y for x, y in zip(a, b))

def is_printable_ascii(data):
    return all(32 <= x <= 126 or x in (10, 13) for x in data)

def analyze_xors(by_length):
    print("\n=== XOR Analysis ===")
    for length, cts in sorted(by_length.items()):
        if len(cts) < 2:
            continue

        print(f"\nAnalyzing ciphertexts of length {length}:")
        for (i1, ct1), (i2, ct2) in itertools.combinations(cts, 2):
            xored = xor_bytes(ct1, ct2)
            hex_result = xored.hex()

            # Try to convert to ASCII if it looks printable
            ascii_repr = ''
            if is_printable_ascii(xored):
                try:
                    ascii_repr = xored.decode('ascii')
                    print(f"\nPotential plaintext found!")
                    print(f"XOR of ciphertext {i1} and {i2}:")
                    print(f"ASCII: {ascii_repr}")
                    print(f"HEX: {hex_result}")
                except:
                    pass

            # Look for repeating patterns in hex
            chunks = [hex_result[i:i+8] for i in range(0, len(hex_result), 8)]
            repeats = defaultdict(int)
            for chunk in chunks:
                repeats[chunk] += 1

            # Print notable patterns
            notable = {k: v for k, v in repeats.items() if v > 1}
            if notable:
                print(f"\nRepeating patterns in XOR of CT{i1} ^ CT{i2}:")
                for pattern, count in notable.items():
                    print(f"Pattern {pattern} appears {count} times")

def main():
    print("Reading and decoding ciphertexts...")
    ciphertexts = read_ciphertexts()
    print(f"Found {len(ciphertexts)} ciphertexts")

    by_length = analyze_lengths(ciphertexts)
    analyze_xors(by_length)

if __name__ == '__main__':
    main()

#!/usr/bin/env python3
import base64
import string
from itertools import combinations
from collections import Counter

def load_ciphertexts():
    ciphertexts = []
    with open('/home/ctfplayer/ctf_files/assignment.txt', 'r') as f:
        content = f.read()
        # Split by newlines and filter out non-base64 lines
        lines = [line.strip() for line in content.split('\n')]
        for line in lines:
            try:
                if line and not line.startswith('#') and not line.startswith('-') and '=' in line:
                    decoded = base64.b64decode(line.strip())
                    ciphertexts.append(decoded)
            except:
                continue
    return ciphertexts

def xor_bytes(a, b):
    return bytes([x ^ y for x, y in zip(a, b)])

def is_printable(text):
    return all(chr(x) in string.printable for x in text)

# Try to decrypt using a known plaintext
def try_decrypt(ciphertext, known_pt, position=0):
    if position + len(known_pt) > len(ciphertext):
        return None
    # Get the keystream for the known position
    keystream = xor_bytes(ciphertext[position:position + len(known_pt)], 
                         known_pt.encode())
    # Try to decrypt the rest using the keystream
    result = []
    for i, c in enumerate(ciphertext):
        k = keystream[i % len(keystream)] if i >= position else c
        result.append(c ^ k if i >= position else c)
    return bytes(result)

def find_repeating_blocks(ciphertexts, block_size=16):
    blocks = {}
    for idx, ct in enumerate(ciphertexts):
        for i in range(0, len(ct) - block_size + 1):
            block = ct[i:i + block_size]
            if block in blocks:
                blocks[block].append((idx, i))
            else:
                blocks[block] = [(idx, i)]
    return {k: v for k, v in blocks.items() if len(v) > 1}

def analyze_keystream(ct1, ct2):
    keystream = xor_bytes(ct1, ct2)
    print(f"XORed result ({len(keystream)} bytes):")
    for i in range(0, len(keystream), 16):
        block = keystream[i:i+16]
        hex_str = ' '.join(f'{b:02x}' for b in block)
        ascii_str = ''.join(chr(b) if 32 <= b <= 126 else '.' for b in block)
        print(f"{i:04x}  {hex_str:<48}  |{ascii_str}|")
    return keystream

def main():
    ciphertexts = load_ciphertexts()
    print(f"Found {len(ciphertexts)} ciphertexts")

    # Look for repeating blocks
    print("\nLooking for repeating blocks...")
    repeating = find_repeating_blocks(ciphertexts)
    for block, positions in repeating.items():
        if len(positions) > 1:
            print(f"\nRepeating block found in {len(positions)} positions:")
            print(f"Block (hex): {' '.join(f'{b:02x}' for b in block)}")
            print("Positions (ciphertext_idx, offset):")
            for idx, pos in positions:
                print(f"  Ciphertext {idx}, offset {pos}")

    # Known plaintext attacks
    known_plaintexts = [
        "secret:", 
        "flag{",
        "#!/usr/bin/env python",
        "/tmp/",
        "/usr/",
        "/etc/",
        "import",
        "cat "
    ]

    print("\nTrying known plaintext attacks...")
    for ct_idx, ct in enumerate(ciphertexts):
        for pt in known_plaintexts:
            # Try at multiple positions
            for pos in range(len(ct) - len(pt) + 1):
                decrypted = try_decrypt(ct, pt, pos)
                if decrypted:
                    # Check if decryption looks printable
                    printable_ratio = sum(1 for b in decrypted if 32 <= b <= 126) / len(decrypted)
                    if printable_ratio > 0.7:
                        print(f"\nPossible decryption in ciphertext {ct_idx}:")
                        print(f"Used known plaintext: {pt!r} at position {pos}")
                        try:
                            decoded = decrypted.decode('ascii', errors='ignore')
                            print(f"Decrypted (ascii): {decoded!r}")
                        except:
                            print(f"Decrypted (hex): {' '.join(f'{b:02x}' for b in decrypted)}")

    # Analyze pairs of equal length ciphertexts
    print("\nAnalyzing pairs of equal length ciphertexts...")
    by_length = {}
    for idx, ct in enumerate(ciphertexts):
        length = len(ct)
        if length not in by_length:
            by_length[length] = []
        by_length[length].append((idx, ct))

    for length, cts in by_length.items():
        if len(cts) > 1:
            print(f"\nAnalyzing ciphertexts of length {length}...")
            for (idx1, ct1), (idx2, ct2) in combinations(cts, 2):
                print(f"\nComparing ciphertext {idx1} with {idx2}")
                keystream = analyze_keystream(ct1, ct2)

if __name__ == '__main__':
    main()

