from pwn import *
import base64
import string
import itertools

def decode_b64(s):
    try:
        return base64.b64decode(s)
    except:
        return None

def xor_bytes(a, b):
    return bytes(x ^ y for x, y in zip(a, b))

def is_printable(s):
    return all(c in string.printable.encode() for c in s)

def score_text(text):
    # Score based on character frequency in English
    freq = {
        'e': 12.7, 't': 9.1, 'a': 8.2, 'o': 7.5, 'i': 7.0,
        'n': 6.7, 's': 6.3, 'h': 6.1, 'r': 6.0, 'd': 4.3
    }
    try:
        text = text.lower().decode('ascii', errors='ignore')
        score = sum(freq.get(c, 0) for c in text)
        return score
    except:
        return 0

def crib_drag(ct1, ct2, crib):
    xored = xor_bytes(ct1, ct2)
    results = []

    for i in range(len(xored) - len(crib) + 1):
        crib_xored = xor_bytes(xored[i:i+len(crib)], crib.encode())
        if is_printable(crib_xored):
            p1 = xor_bytes(ct1[i:i+len(crib)], crib.encode())
            p2 = xor_bytes(ct2[i:i+len(crib)], crib.encode())
            if is_printable(p1) and is_printable(p2):
                results.append((i, p1.decode(), p2.decode()))

    return results

def main():
    # Load ciphertexts
    ciphertexts = []
    with open('/home/ctfplayer/ctf_files/assignment.txt', 'r') as f:
