        "this", "that", "with", "from", "#!/u", "/tmp",
        "python", ".txt", "open", "read", "write"
    ]

    # For each length group, try XORing pairs and crib dragging
    for length, cts in by_length.items():
        print(f"\nAnalyzing ciphertexts of length {length}...")
        if len(cts) < 2:
            continue

        for (i1, ct1), (i2, ct2) in itertools.combinations(cts, 2):
            xored = xor_bytes(ct1, ct2)

            # Look for patterns that might indicate plaintext XOR plaintext
            if any(x < 128 for x in xored):  # ASCII range
                print(f"\nInteresting XOR between ciphertext {i1} and {i2}")

                # Try each crib
                for crib in cribs:
                    results = crib_drag(ct1, ct2, crib)
                    for pos, p1, p2 in results:
