#!/usr/bin/env python3
from pwn import *
import base64
import string
import itertools

def decode_b64(s):
    try:
        return base64.b64decode(s)
    except:
        return None

def xor_bytes(a, b):
    return bytes(x ^ y for x, y in zip(a, b))

def is_printable(s):
    return all(c in string.printable.encode() for c in s)

def find_repeating_blocks(ct, block_size=16):
    blocks = [ct[i:i+block_size] for i in range(0, len(ct), block_size)]
    repeats = []
    for i, block1 in enumerate(blocks):
        for j, block2 in enumerate(blocks[i+1:], i+1):
            if block1 == block2:
                repeats.append((i, j))
    return repeats

def score_potential_key(key_part, cts):
    score = 0
    for ct in cts:
        if len(ct) < len(key_part):
            continue
        pt = xor_bytes(ct[:len(key_part)], key_part)
        if is_printable(pt):
            score += 1
    return score

def try_recover_key(ct1, ct2, known_text, pos=0):
    xored = xor_bytes(ct1[pos:], ct2[pos:])
    known_bytes = known_text.encode()
    potential_key1 = xor_bytes(ct1[pos:pos+len(known_bytes)], known_bytes)
    potential_key2 = xor_bytes(ct2[pos:pos+len(known_bytes)], known_bytes)
    return potential_key1, potential_key2

def main():
    # Load ciphertexts
    ciphertexts = []
    with open('/home/ctfplayer/ctf_files/assignment.txt', 'r') as f:
        for line in f:
            line = line.strip()
            if '=' in line:
                ct = decode_b64(line)
                if ct:
                    ciphertexts.append(ct)

    print(f"Analyzing {len(ciphertexts)} ciphertexts")

    # Try to find same-length pairs with high similarity
    by_length = {}
    for i, ct in enumerate(ciphertexts):
        l = len(ct)
        if l not in by_length:
            by_length[l] = []
        by_length[l].append((i, ct))

    # Key fragment candidates from various positions
    key_fragments = []

    # Analyze each length group
    for length, cts in by_length.items():
        if len(cts) < 2:
            continue

        print(f"\nAnalyzing {len(cts)} ciphertexts of length {length}")

        # Look for repeating blocks
        for i, (idx, ct) in enumerate(cts):
            repeats = find_repeating_blocks(ct)
            if repeats:
                print(f"Ciphertext {idx} has repeating blocks at positions: {repeats}")

        # XOR combinations looking for patterns
        for (i1, ct1), (i2, ct2) in itertools.combinations(cts, 2):
            xored = xor_bytes(ct1, ct2)

            # Check for ASCII patterns in the XOR result
            ascii_ratio = sum(1 for x in xored if 32 <= x <= 126) / len(xored)
            if ascii_ratio > 0.7:  # High ASCII ratio indicates potential plaintext XOR
                print(f"\nHigh ASCII ratio ({ascii_ratio:.2f}) between ciphertexts {i1} and {i2}")

                # Try common plaintext patterns
                patterns = [
                    "secret:", "the ", "and ", "flag{", "}", 
                    "python", ".txt", "password", "admin", "user"
                ]

                for pattern in patterns:
                    # Try pattern at different positions
                    for pos in range(min(32, len(xored)-len(pattern))):
                        k1, k2 = try_recover_key(ct1, ct2, pattern, pos)

                        # Test these key fragments against other ciphertexts
                        score1 = score_potential_key(k1, ciphertexts)
                        score2 = score_potential_key(k2, ciphertexts)

                        if score1 > len(ciphertexts) // 3:
                            print(f"Potential key fragment from pattern '{pattern}' at pos {pos}:")
                            print(f"Key fragment: {k1.hex()}")
                            key_fragments.append((k1, pos, score1))

                        if score2 > len(ciphertexts) // 3:
                            print(f"Potential key fragment from pattern '{pattern}' at pos {pos}:")
                            print(f"Key fragment: {k2.hex()}")
                            key_fragments.append((k2, pos, score2))

    # Try to reconstruct messages using best key fragments
    print("\nAttempting message reconstruction:")
    key_fragments.sort(key=lambda x: (-x[2], x[1]))  # Sort by score desc, position asc

    reconstructed_texts = set()
    for kf, pos, score in key_fragments[:10]:  # Try top 10 key fragments
        for ct in ciphertexts:
            if len(ct) >= pos + len(kf):
                pt = xor_bytes(ct[pos:pos+len(kf)], kf)
                if is_printable(pt):
                    try:
                        text = pt.decode()
                        if len(text.strip()) >= 4:  # Only keep meaningful fragments
                            reconstructed_texts.add(text.strip())
                    except:
                        continue

    print("\nReconstructed text fragments:")
    for text in sorted(reconstructed_texts, key=len, reverse=True):
        print(f"- {text}")

    print("\nConnecting to server to try reconstructed texts...")
    try:
        r = remote('crypto.chal.csaw.io', 8000)
        r.recvuntil(b'trade with you...\n')

        for text in sorted(reconstructed_texts, key=len, reverse=True):
            print(f"\nTrying text: {text}")
            r.sendline(text.encode())
            resp = r.recvline().decode().strip()
            print(f"Server response: {resp}")
            if 'flag{' in resp.lower():
                print(f"Found flag: {resp}")
                break

        r.close()
    except Exception as e:
        print(f"Error connecting to server: {e}")

if __name__ == '__main__':
    main()

#!/usr/bin/env python3
from pwn import *
import base64
import string
import itertools
from collections import defaultdict

def decode_b64(s):
    try:
        return base64.b64decode(s)
    except:
        return None

def xor_bytes(a, b):
    return bytes(x ^ y for x, y in zip(a, b))

def is_likely_text(s):
    # Check if the text contains mostly printable characters
    printable = sum(1 for c in s if chr(c) in string.printable)
    return printable / len(s) > 0.85

def score_text(s):
    # Score text based on character frequency in English
    freq = {'e': 12.7, 't': 9.1, 'a': 8.2, 'o': 7.5, 'i': 7.0, 'n': 6.7, 's': 6.3, 
            'h': 6.1, 'r': 6.0, 'd': 4.3, 'l': 4.0, 'u': 2.8}
    score = 0
    try:
        text = s.decode('ascii').lower()
        for c in text:
            if c in freq:
                score += freq[c]
        # Bonus for common words
        common_words = ['the', 'be', 'to', 'of', 'and', 'in', 'that', 'have']
        for word in common_words:
            if word in text:
                score += 10
    except:
        return 0
    return score

def crib_drag(ct1, ct2, crib, start_pos=0):
    results = []
    if len(crib) == 0:
        return results

    xored = xor_bytes(ct1, ct2)
    crib_bytes = crib.encode()

    for i in range(start_pos, len(xored) - len(crib_bytes) + 1):
        # XOR the crib with the XORed ciphertexts at this position
        key_stream = xor_bytes(xored[i:i+len(crib_bytes)], crib_bytes)

        # Try this key stream on both ciphertexts
        pt1 = xor_bytes(ct1[i:i+len(crib_bytes)], key_stream)
        pt2 = xor_bytes(ct2[i:i+len(crib_bytes)], key_stream)

        # Check if both results look like text
        if is_likely_text(pt1) and is_likely_text(pt2):
            try:
                results.append({
                    'position': i,
                    'pt1': pt1.decode('ascii'),
                    'pt2': pt2.decode('ascii'),
                    'score': score_text(pt1) + score_text(pt2)
                })
            except:
                continue

    return sorted(results, key=lambda x: x['score'], reverse=True)

def main():
    # Read and parse ciphertexts
    ciphertexts = []
    with open('/home/ctfplayer/ctf_files/assignment.txt', 'r') as f:
        lines = f.read().split('\n')
        for line in lines:
            line = line.strip()
            if '=' in line:  # Base64 encoded lines end with =
                ct = decode_b64(line)
                if ct:
                    ciphertexts.append(ct)

    print(f"Found {len(ciphertexts)} ciphertexts")

    # Group ciphertexts by length for analysis
    by_length = defaultdict(list)
    for i, ct in enumerate(ciphertexts):
        by_length[len(ct)].append((i, ct))

    # Print length distribution
    print("\nCiphertext length distribution:")
    for length, cts in sorted(by_length.items()):
        print(f"Length {length}: {len(cts)} ciphertexts")

    # Analyze pairs of same-length ciphertexts
    cribs = [
        "secret:", "flag", "password", "user:", "admin:", 
        "file:", "/etc/", "/home", "./", "txt", 
        "python", "bash", "shell", "error:", "success:",
        "{", "}", "flag{", "}", "_", "-"
    ]

    # Store promising results
    promising_results = []

    for length, cts in by_length.items():
        if len(cts) < 2:
            continue

        print(f"\nAnalyzing ciphertexts of length {length}")
        for (i1, ct1), (i2, ct2) in itertools.combinations(cts, 2):
            print(f"\nTesting pair {i1} vs {i2}")

            for crib in cribs:
                results = crib_drag(ct1, ct2, crib)
                if results:
                    for r in results[:3]:  # Show top 3 results for each crib
                        print(f"\nCrib '{crib}' at position {r['position']}:")
                        print(f"Text 1: {r['pt1']}")
                        print(f"Text 2: {r['pt2']}")
                        print(f"Score: {r['score']}")

                        if r['score'] > 50:  # High scoring results
                            promising_results.append(r)

    # Check for possible flag content
    print("\nChecking for potential flags...")
    r = remote('crypto.chal.csaw.io', 8000)
    r.recvuntil(b'trade with you...\n')

    tried_texts = set()
    for result in promising_results:
        for text in [result['pt1'], result['pt2']]:
            if text in tried_texts:
                continue

            # Clean up the text
            text = text.strip()
            if len(text) < 4:  # Skip very short texts
                continue

            tried_texts.add(text)
            print(f"\nTrying text: {text}")
            r.sendline(text.encode())
            resp = r.recvline().decode().strip()
            print(f"Server response: {resp}")

            if 'flag{' in resp.lower():
                print(f"Found flag: {resp}")
                r.close()
                return

    r.close()

if __name__ == '__main__':
    main()

