def get_printable_solutions(ct1, ct2, known_text, pos=0):
    # Returns possible solutions when XORing ciphertexts with known text at given position
    results = []
    xored = xor_bytes(ct1, ct2)
    known = known_text.encode()

    if pos + len(known) > len(xored):
        return results

    keystream = xor_bytes(xored[pos:pos+len(known)], known)
    pt1 = xor_bytes(ct1[pos:pos+len(known)], keystream)
    pt2 = xor_bytes(ct2[pos:pos+len(known)], keystream)

    # Check if both results are printable ASCII
    if all(32 <= c <= 126 for c in pt1) and all(32 <= c <= 126 for c in pt2):
        results.append({
            'offset': pos,
            'pt1': pt1.decode(),
            'pt2': pt2.decode(),
            'keystream': keystream
        })

    return results

