    ]

    potential_secrets = []

    # Try each pair of ciphertexts
    for ct1, ct2 in itertools.combinations(common_cts, 2):
        xored = xor_bytes(ct1, ct2)

        # Try each word at each position
        for word in words:
            word_bytes = word.encode()
            for pos in range(len(xored) - len(word_bytes)):
                # XOR the word with the XORed ciphertexts
                key_stream = xor_bytes(xored[pos:pos+len(word_bytes)], word_bytes)

                # Get potential plaintexts
                pt1 = xor_bytes(ct1[pos:pos+len(word_bytes)], key_stream)
                pt2 = xor_bytes(ct2[pos:pos+len(word_bytes)], key_stream)

                if is_printable(pt1) and is_printable(pt2):
                    score1 = score_text(pt1)
