#!/usr/bin/env python3
import base64
from collections import defaultdict
import itertools

def read_ciphertexts():
    with open('/home/ctfplayer/ctf_files/assignment.txt', 'r') as f:
        ciphertexts = []
        current = []
        reading = False
        for line in f:
            if line.strip() == '':
                if reading and current:
                    ciphertexts.append(''.join(current))
                    current = []
                reading = False
            elif len(line.strip()) > 0 and all(c in 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/=' for c in line.strip()):
                reading = True
                current.append(line.strip())
        if current:
            ciphertexts.append(''.join(current))
    return [base64.b64decode(ct) for ct in ciphertexts]

def xor_bytes(a, b):
    return bytes(x ^ y for x, y in zip(a, b))

def find_key_reuse(ciphertexts):
    results = []
    for ct1, ct2 in itertools.combinations(ciphertexts, 2):
        min_len = min(len(ct1), len(ct2))
        xored = xor_bytes(ct1[:min_len], ct2[:min_len])

        # Look for ASCII text patterns when XORing
        for i in range(len(xored) - 5):
            if all(32 <= x <= 126 for x in xored[i:i+5]):
                results.append({
                    'ct1': ct1.hex()[:20] + "...",
                    'ct2': ct2.hex()[:20] + "...",
                    'offset': i,
                    'ascii_text': xored[i:i+20]
                })
    return results

def analyze_reuse_patterns(ciphertexts):
    # Find ciphertexts that share the same prefix (same keystream)
    prefixes = defaultdict(list)
    for i, ct in enumerate(ciphertexts):
        prefix = ct[:16]  # Look at first block
        prefixes[prefix].append(i)

    return {k.hex(): v for k, v in prefixes.items() if len(v) > 1}

def main():
    print("Loading ciphertexts...")
    ciphertexts = read_ciphertexts()
    print(f"Found {len(ciphertexts)} ciphertexts")

    print("\nAnalyzing patterns...")
    reuse_patterns = analyze_reuse_patterns(ciphertexts)
    if reuse_patterns:
        print("\nFound ciphertexts with identical prefixes:")
        for prefix, indices in reuse_patterns.items():
            print(f"Prefix {prefix}: appears in ciphertexts {indices}")

    print("\nAnalyzing potential plaintext patterns...")
    xor_results = find_key_reuse(ciphertexts)

    with open('potential_secrets.txt', 'w') as f:
        f.write("=== Potential Keystream Reuse Analysis ===\n\n")

        for result in xor_results:
            output = (f"Found ASCII pattern at offset {result['offset']}\n"
                     f"CT1: {result['ct1']}\n"
                     f"CT2: {result['ct2']}\n"
                     f"XOR result (ASCII): {result['ascii_text']}\n\n")
            f.write(output)
            print(output)

if __name__ == '__main__':
    main()
